diff:
diff --git a/grub-core/osdep/unix/efivar.c b/grub-core/osdep/unix/efivar.c
index 19b6550..c85fa59 100644
--- a/grub-core/osdep/unix/efivar.c
+++ b/grub-core/osdep/unix/efivar.c
@@ -537,6 +537,21 @@ devices_equal (const_efidp a, const_efidp b)
   return false;
 }

+static const char*
+get_os_dev (grub_disk_t disk, const char *efidir)
+{
+  if (disk->dev->id == GRUB_DISK_DEVICE_BIOSDISK_ID) {
+    return grub_util_biosdisk_get_osdev (disk);
+  } else if (disk->dev->id == GRUB_DISK_DEVICE_DISKFILTER_ID) {
+    char **efidir_device_names = grub_guess_root_devices (efidir);
+    if (!efidir_device_names || !efidir_device_names[0])
+      grub_util_error (_("cannot find a device for %s (is /dev mounted?)"),
+                             efidir);
+    return efidir_device_names[0];
+  }
+  return NULL;
+}
+
 int
 grub_install_efivar_register_efi (grub_device_t efidir_grub_dev,
 				  const char *efidir, const char *efifile_path,
@@ -563,7 +578,7 @@ grub_install_efivar_register_efi (grub_device_t efidir_grub_dev,
     }

   is_boot_efi = strstr (efidir, "/boot/efi") != NULL;
-  efidir_disk = grub_util_biosdisk_get_osdev (efidir_grub_dev->disk);
+  efidir_disk = get_os_dev (efidir_grub_dev->disk, efidir);
   efidir_part = efidir_grub_dev->disk->partition ? efidir_grub_dev->disk->partition->number + 1 : 1;
   alternatives = get_alternative_esps ();
